package server

import (
	"context"
	"time"

	"github.com/BonfireTrunk/lorvik/internal/domain"
	"github.com/BonfireTrunk/lorvik/internal/query"
)

// Store is everything the server needs from persistence. It is declared here,
// in the consuming package, and implemented by internal/store on Postgres.
// Tests implement it with an in-memory fake.
//
// Conventions:
//   - Every method takes ctx first. Ids are generated by the caller
//     (domain.IDGen) and passed in; the store never invents an id.
//   - Not-found returns an error wrapping domain.ErrNotFound.
//   - Writes that take an expected version return domain.ErrVersionConflict
//     when the stored version differs; the caller re-reads and retries.
//   - Card numbers are allocated by the store from the project's counter and
//     never reused.
//   - Mutations do not emit events. The caller appends events in the same
//     transaction through WithTx so a write and its event are atomic.
//   - Lists page by keyset: a filter carries an optional cursor (the sort key
//     of the row to continue from) and a direction; the store returns the
//     page plus Remaining, the number of further rows in that direction,
//     counted up to query.RemainingCap.
type Store interface {
	// WithTx runs fn inside one transaction. The Store passed to fn shares
	// the transaction; the outer Store must not be used inside fn.
	WithTx(ctx context.Context, fn func(tx Store) error) error
	// WithSnapshot runs fn in one read-only transaction whose statements all
	// see the same snapshot.
	WithSnapshot(ctx context.Context, fn func(tx Store) error) error

	// Ping checks connectivity for the health endpoint.
	Ping(ctx context.Context) error

	OrgStore
	ActorStore
	ProjectStore
	CardStore
	LockStore
	RequestKeyStore
	NoteStore
	RefStore
	EventStore
	SearchStore
}

// OrgStore manages tenants.
type OrgStore interface {
	CreateOrg(ctx context.Context, o domain.Org) (domain.Org, error)
	GetOrg(ctx context.Context, id domain.ID) (domain.Org, error)
	// UpdateOrg writes name, status and settings.
	UpdateOrg(ctx context.Context, o domain.Org) (domain.Org, error)
	// ListOrgs returns every org, for background jobs.
	ListOrgs(ctx context.Context) ([]domain.Org, error)
}

// ActorStore manages users, identities, memberships, agents and tokens.
type ActorStore interface {
	CreateUser(ctx context.Context, u domain.User) (domain.User, error)
	GetUser(ctx context.Context, id domain.ID) (domain.User, error)
	// LockUser is GetUser with a row lock held to the end of the transaction.
	LockUser(ctx context.Context, id domain.ID) (domain.User, error)
	// GetUsers returns the users among ids that exist, in no particular order.
	GetUsers(ctx context.Context, ids []domain.ID) ([]domain.User, error)
	// UpdateUser writes login, name, email, avatar, locale, timezone, status.
	UpdateUser(ctx context.Context, u domain.User) (domain.User, error)

	CreateIdentity(ctx context.Context, i domain.Identity) (domain.Identity, error)
	// GetIdentity is the login lookup.
	GetIdentity(ctx context.Context, provider domain.Provider, providerID string) (domain.Identity, error)
	ListIdentities(ctx context.Context, userID domain.ID) ([]domain.Identity, error)
	// UpdateIdentity writes secret, login and last_login_at.
	UpdateIdentity(ctx context.Context, i domain.Identity) error
	// DeleteIdentity removes the user's identity, or returns ErrNotFound.
	DeleteIdentity(ctx context.Context, userID, id domain.ID) error

	// PutMembership inserts or replaces the actor's org membership.
	PutMembership(ctx context.Context, m domain.Membership) (domain.Membership, error)
	// GetMembership returns ErrNotFound when no row exists, whatever its status.
	GetMembership(ctx context.Context, orgID domain.ID, actor domain.ActorRef) (domain.Membership, error)
	// LockMembership is GetMembership with a row lock held to the end of the
	// transaction, so a decision read on the row cannot be overtaken by
	// another writer before it is written back.
	LockMembership(ctx context.Context, orgID domain.ID, actor domain.ActorRef) (domain.Membership, error)
	// CountOrgPeople counts the org's people with an active membership on
	// an active account.
	CountOrgPeople(ctx context.Context, orgID domain.ID) (int, error)
	// CountOrgContents counts the org's projects other than its global one, and
	// the cards of all its projects.
	CountOrgContents(ctx context.Context, orgID domain.ID) (projects, cards int, err error)
	// LockOrgOwners returns the org's active owners, people with an active
	// account only, each membership row locked to the end of the transaction.
	LockOrgOwners(ctx context.Context, orgID domain.ID) ([]domain.Membership, error)
	// ListMemberships returns one page of an org's members and how many follow,
	// alive ones only unless the filter's All is set.
	ListMemberships(ctx context.Context, orgID domain.ID, f query.MemberFilter) ([]domain.Membership, int, error)
	// ListMembershipsForActor returns the alive memberships of one actor across orgs.
	ListMembershipsForActor(ctx context.Context, actor domain.ActorRef) ([]domain.Membership, error)
	// ListOpenMembershipsForActor adds the pending rows: invitations and
	// requests to join.
	ListOpenMembershipsForActor(ctx context.Context, actor domain.ActorRef) ([]domain.Membership, error)

	PutProjectMember(ctx context.Context, m domain.ProjectMember) (domain.ProjectMember, error)
	GetProjectMember(ctx context.Context, projectID domain.ID, actor domain.ActorRef) (domain.ProjectMember, error)
	ListProjectMembers(ctx context.Context, projectID domain.ID, f query.MemberFilter) ([]domain.ProjectMember, int, error)
	// ListProjectMembersForActor returns the actor's alive project roles
	// within one org, for the visibility filter.
	ListProjectMembersForActor(ctx context.Context, orgID domain.ID, actor domain.ActorRef) ([]domain.ProjectMember, error)
	// ListAgentRequests returns the pending requests of agents to join the
	// org's projects that ownerID decides, oldest first.
	ListAgentRequests(ctx context.Context, orgID, ownerID domain.ID) ([]domain.ProjectMember, error)
	// TouchAgentSession records that the session (a base label) used the
	// agent's token at now; a row seen less than a minute ago is left alone.
	TouchAgentSession(ctx context.Context, agentID domain.ID, session string, now time.Time) error
	// TrimAgentSessions deletes the agent's sessions beyond the keep most
	// recently seen, except those that hold a grant.
	TrimAgentSessions(ctx context.Context, agentID domain.ID, keep int) error
	// SetAgentSessionName stores what people call the session (a base
	// label), creating its row when it was never seen; empty clears it.
	SetAgentSessionName(ctx context.Context, agentID domain.ID, session, name string, now time.Time) error
	// ListAgentSessions returns up to limit sessions seen using the agent's
	// token, most recently seen first.
	ListAgentSessions(ctx context.Context, agentID domain.ID, limit int) ([]domain.AgentSession, error)
	// ListAgentSessionsByLabel returns the named sessions the agent was seen
	// in, most recently seen first; a label never seen is absent.
	ListAgentSessionsByLabel(ctx context.Context, agentID domain.ID, labels []string) ([]domain.AgentSession, error)
	// PutAgentSessionGrant inserts or replaces the rights of one session of
	// an agent in one project.
	PutAgentSessionGrant(ctx context.Context, g domain.AgentSessionGrant) (domain.AgentSessionGrant, error)
	// GetAgentSessionGrant returns the row whatever its status; ErrNotFound
	// when none.
	GetAgentSessionGrant(ctx context.Context, projectID, agentID domain.ID, session string) (domain.AgentSessionGrant, error)
	// ListAgentSessionGrants returns the alive grants of one agent across
	// projects.
	ListAgentSessionGrants(ctx context.Context, agentID domain.ID) ([]domain.AgentSessionGrant, error)
	// EndAgentSessionGrant takes back a grant that is alive and whose end is
	// at or before the given time; ErrNotFound for any other.
	EndAgentSessionGrant(ctx context.Context, projectID, agentID domain.ID, session string, before time.Time) (domain.AgentSessionGrant, error)
	// ListEndedAgentSessionGrants returns alive grants whose end is at or
	// before the given time, soonest first.
	ListEndedAgentSessionGrants(ctx context.Context, before time.Time, limit int) ([]domain.AgentSessionGrant, error)
	// GetAgentJoinRule returns a user's own join rule for one project;
	// ErrNotFound means follow.
	GetAgentJoinRule(ctx context.Context, projectID, userID domain.ID) (domain.AgentJoinRule, error)
	PutAgentJoinRule(ctx context.Context, r domain.AgentJoinRule) (domain.AgentJoinRule, error)
	DeleteAgentJoinRule(ctx context.Context, projectID, userID domain.ID) error
	// HasProjectMembership reports whether the actor has an alive role in
	// any project of the org.
	HasProjectMembership(ctx context.Context, orgID domain.ID, actor domain.ActorRef) (bool, error)

	CreateAgent(ctx context.Context, a domain.Agent) (domain.Agent, error)
	GetAgent(ctx context.Context, id domain.ID) (domain.Agent, error)
	// LockAgent is GetAgent with a row lock held to the end of the
	// transaction, so a status read on the row cannot be overtaken by another
	// writer before it is written back or acted on.
	LockAgent(ctx context.Context, id domain.ID) (domain.Agent, error)
	GetAgents(ctx context.Context, ids []domain.ID) ([]domain.Agent, error)
	// ListAgents returns an org's agents; alive and pending unless all is
	// set, which adds the revoked and the removed.
	ListAgents(ctx context.Context, orgID domain.ID, all bool) ([]domain.Agent, error)
	// ListAgentsPage returns one page of the org's agents and how many follow.
	ListAgentsPage(ctx context.Context, orgID domain.ID, f query.AgentFilter) ([]domain.Agent, int, error)
	// UpdateAgent writes name, harness, machine and status.
	UpdateAgent(ctx context.Context, a domain.Agent) (domain.Agent, error)

	CreateToken(ctx context.Context, t domain.Token) (domain.Token, error)
	// GetTokenByHash is the authentication lookup. Revoked and expired tokens
	// are still returned so the caller can give a precise error.
	GetTokenByHash(ctx context.Context, hash []byte) (domain.Token, error)
	GetToken(ctx context.Context, id domain.ID) (domain.Token, error)
	// LockToken is GetToken with a row lock held to the end of the
	// transaction; every status change of one token goes through it.
	LockToken(ctx context.Context, id domain.ID) (domain.Token, error)
	ListTokens(ctx context.Context, orgID domain.ID, actor domain.ActorRef, pg query.Page, after *query.TokenCursor) ([]domain.Token, int, error)
	// UpdateToken writes status, expires_at and replaced_by.
	UpdateToken(ctx context.Context, t domain.Token) error
	// TouchToken records last use. Implementations may coalesce writes.
	TouchToken(ctx context.Context, id domain.ID, at time.Time) error
	// RevokeTokensForActor revokes every live token of the actor in the org,
	// including a successor minted by a rotation that ran concurrently.
	RevokeTokensForActor(ctx context.Context, orgID domain.ID, actor domain.ActorRef) error
}

// ProjectStore manages projects.
type ProjectStore interface {
	CreateProject(ctx context.Context, p domain.Project) (domain.Project, error)
	GetProject(ctx context.Context, id domain.ID) (domain.Project, error)
	GetProjectBySlug(ctx context.Context, orgID domain.ID, slug string) (domain.Project, error)
	ListProjects(ctx context.Context, orgID domain.ID) ([]domain.Project, error)
	// UpdateProject writes name, description, visibility, concurrency, lease and status.
	UpdateProject(ctx context.Context, p domain.Project) (domain.Project, error)
	// CountCards returns per-status counts plus the open question count.
	CountCards(ctx context.Context, projectID domain.ID) (query.CardCounts, error)
	// CountOpenQuestionsBy counts the open questions the actor asked.
	CountOpenQuestionsBy(ctx context.Context, projectID domain.ID, actor domain.ActorRef) (int, error)
}

// CardStore manages cards, claims, links, comments and read marks.
type CardStore interface {
	// CreateCard allocates the number from the project and sets version 1.
	CreateCard(ctx context.Context, c domain.Card) (domain.Card, error)
	GetCard(ctx context.Context, id domain.ID) (domain.Card, error)
	GetCards(ctx context.Context, ids []domain.ID) ([]domain.Card, error)
	GetCardByNumber(ctx context.Context, projectID domain.ID, number int64) (domain.Card, error)
	// ListCards returns one page and how many more rows follow it.
	ListCards(ctx context.Context, projectID domain.ID, f query.CardFilter) (cards []domain.Card, remaining int, err error)
	// ListCardsIn is ListCards across several projects: newest first by id,
	// and query.CardCursor.ID is the cursor.
	ListCardsIn(ctx context.Context, projectIDs []domain.ID, f query.CardFilter) (cards []domain.Card, remaining int, err error)
	// ListUnfolded returns the project's done cards that have no parent and
	// no fold mark, newest closed first.
	ListUnfolded(ctx context.Context, projectID domain.ID, page query.Page, cur *query.UnfoldedCursor) (cards []domain.Card, remaining int, err error)
	// NextReady returns the best ready, unclaimed, unblocked task by priority
	// then number that is unassigned or assigned to actor and whose lane has
	// neither a working card nor a lock live at now, or domain.ErrNotFound.
	NextReady(ctx context.Context, projectID domain.ID, actor domain.ActorRef, now time.Time) (domain.Card, error)
	// CountOnBusyLanes counts, per lane, the cards NextReady would offer actor
	// but for a working card or a live lock in the same lane. Lanes come in
	// name order.
	CountOnBusyLanes(ctx context.Context, projectID domain.ID, actor domain.ActorRef, now time.Time) ([]query.LaneCount, error)
	// UpdateCard writes every mutable field of c where the stored version
	// equals expectedVersion, increments the version, and returns the result.
	UpdateCard(ctx context.Context, c domain.Card, expectedVersion int64) (domain.Card, error)
	// SnapshotCardRevision keeps the card's current title, body and page as a
	// revision at version expectedVersion, attributed to by; the page is kept
	// only when pageChanged. It returns ErrVersionConflict if the stored
	// version differs.
	SnapshotCardRevision(ctx context.Context, cardID domain.ID, expectedVersion int64, revisionID domain.ID, by domain.ActorRef, at time.Time, pageChanged bool) error
	ListCardRevisions(ctx context.Context, cardID domain.ID, pg query.HistoryPage) ([]domain.CardRevision, error)
	GetCardRevision(ctx context.Context, cardID domain.ID, version int64) (domain.CardRevision, error)
	// PutCardPage stores the card's HTML page and its visible text for
	// search, replacing any earlier page. The caller sets Card.PageBytes in
	// the same transaction. Lists never read pages.
	PutCardPage(ctx context.Context, cardID domain.ID, html, text string) error
	// DeleteCardPage removes the card's page; no error when it has none.
	DeleteCardPage(ctx context.Context, cardID domain.ID) error
	// GetCardPage returns the card's HTML page, or ErrNotFound when it has none.
	GetCardPage(ctx context.Context, cardID domain.ID) (string, error)
	// ListOpenCardsAssignedTo returns the open cards of the org assigned to
	// the actor.
	ListOpenCardsAssignedTo(ctx context.Context, orgID domain.ID, actor domain.ActorRef) ([]domain.Card, error)
	// ListChildren returns direct children ordered by priority then number.
	ListChildren(ctx context.Context, parentID domain.ID) ([]domain.Card, error)
	// ListFirstChildren returns at most limit children in ListChildren's order.
	ListFirstChildren(ctx context.Context, parentID domain.ID, limit int) ([]domain.Card, error)
	// CountChildrenByStatus counts a card's direct children per status.
	CountChildrenByStatus(ctx context.Context, parentID domain.ID) (map[domain.Status]int, error)

	// GetClaim returns the card's live claim row, or ErrNotFound.
	GetClaim(ctx context.Context, cardID domain.ID) (domain.Claim, error)
	// GetClaims returns the claim rows among cardIDs that exist.
	GetClaims(ctx context.Context, cardIDs []domain.ID) ([]domain.Claim, error)
	// PutClaim inserts or replaces the card's claim.
	PutClaim(ctx context.Context, c domain.Claim) error
	// DeleteClaim removes the card's claim; no error when none exists.
	DeleteClaim(ctx context.Context, cardID domain.ID) error
	// ListClaimsByActor returns the claim rows the actor holds in the org,
	// expired ones included until the sweeper deletes them; callers judge the
	// lease with Claim.Expired.
	ListClaimsByActor(ctx context.Context, orgID domain.ID, actor domain.ActorRef) ([]domain.Claim, error)
	// RenewClaims extends, by the project's lease from now, the caller's live
	// claims that have less than half of that lease left, and returns them.
	// For an agent only the claims taken in session count.
	RenewClaims(ctx context.Context, orgID domain.ID, actor domain.ActorRef, session string, now time.Time) ([]domain.Claim, error)
	// ListEndingClaims returns up to limit live claims whose last call is due
	// by now (Claim.LastCallAt) and whose current expiry has had none.
	ListEndingClaims(ctx context.Context, now time.Time, limit int) ([]domain.Claim, error)
	// MarkClaimEnding records that the last call for the claim ending at
	// expiresAt is written. It reports false when the card's claim no longer
	// ends then, or the call was already recorded.
	MarkClaimEnding(ctx context.Context, cardID domain.ID, expiresAt time.Time) (bool, error)
	// ListExpiredClaims returns up to limit claims whose lease passed by
	// before, for the sweeper.
	ListExpiredClaims(ctx context.Context, before time.Time, limit int) ([]domain.Claim, error)
	// LockExpiredClaim locks the card's claim to the end of the transaction
	// if its lease still passed by before, or returns domain.ErrNotFound.
	LockExpiredClaim(ctx context.Context, cardID domain.ID, before time.Time) (domain.Claim, error)

	AddCardLink(ctx context.Context, l domain.CardLink) error
	RemoveCardLink(ctx context.Context, fromID, toID domain.ID, kind domain.CardLinkKind) error
	// ListCardLinks returns links where the card is source or target.
	ListCardLinks(ctx context.Context, cardID domain.ID) ([]domain.CardLink, error)
	// ListProjectLinks returns one page of the links with an end in the
	// project, ordered by from card id, to card id and kind. visible, when
	// not nil, limits it to links whose two cards are both in those projects.
	// It also returns how many links lie beyond the page, capped at
	// query.RemainingCap.
	ListProjectLinks(ctx context.Context, projectID domain.ID, visible []domain.ID, limit int, after *query.LinkCursor) ([]query.LinkEdge, int, error)
	// ListLiveClaims returns one page of the org's claims whose lease runs
	// past now, ordered by holder kind, holder id, session and card id.
	// projects, when not nil, limits it to claims on cards in those projects.
	// It also returns how many claims lie beyond the page, capped at
	// query.RemainingCap.
	ListLiveClaims(ctx context.Context, orgID domain.ID, projects []domain.ID, now time.Time, limit int, after *query.LiveClaimCursor) ([]query.LiveClaim, int, error)
	// ListProjectMentions returns one page of the references from the
	// project's cards to notes, ordered by card id and note id. visible, when
	// not nil, limits it to notes in those projects. It also returns how many
	// lie beyond the page, capped at query.RemainingCap.
	ListProjectMentions(ctx context.Context, projectID domain.ID, visible []domain.ID, limit int, after *query.MentionCursor) ([]query.MentionEdge, int, error)
	// ListMapGroups returns one page of the project's map groups, ordered by
	// kind, story number and lane: a story with the status counts of its
	// children, a lane with the counts of the cards outside any story that
	// carry it (the lane "" holds those with none). It also returns how many
	// groups lie beyond the page, capped at query.RemainingCap.
	ListMapGroups(ctx context.Context, projectID domain.ID, limit int, after *query.MapGroupRef) ([]query.MapGroup, int, error)
	// ListMapGroupLinks returns one page of the link counts per ordered pair of
	// different map groups and link kind, counting links between cards of the
	// project only, ordered by from group, to group and kind. It also returns
	// how many lie beyond the page, capped at query.RemainingCap.
	ListMapGroupLinks(ctx context.Context, projectID domain.ID, limit int, after *query.MapGroupLinkCursor) ([]query.MapGroupLink, int, error)
	// ListBlockers returns open cards that block cardID.
	ListBlockers(ctx context.Context, cardID domain.ID) ([]domain.Card, error)

	AddComment(ctx context.Context, h domain.Comment) error
	// GetComment returns the comment, or ErrNotFound.
	GetComment(ctx context.Context, id domain.ID) (domain.Comment, error)
	// LatestComment returns the newest comment on the card, or ErrNotFound.
	LatestComment(ctx context.Context, cardID domain.ID) (domain.Comment, error)
	// ListComments returns one page of the card's comments, newest first.
	ListComments(ctx context.Context, cardID domain.ID, pg query.HistoryPage) ([]domain.Comment, error)

	// MarkCardSeen records that the actor saw the card at r.SeenID; an earlier
	// SeenID never replaces a later one.
	MarkCardSeen(ctx context.Context, r domain.CardRead) error
	// ListReplies returns, per card in the project the actor has marked seen,
	// the newest comment by someone else after the mark and how many there
	// are, newest first.
	ListReplies(ctx context.Context, actor domain.ActorRef, projectID, before domain.ID, limit int32) ([]domain.Reply, int, error)
}

// RequestKeyStore remembers the idempotency keys clients sent with a write.
type RequestKeyStore interface {
	// ClaimRequestKey records k unless the actor has used k.Key before. It
	// returns claimed true when k was recorded: the caller owns the key and
	// goes on to write. Otherwise it returns the row already there. It must
	// be the first write of its transaction: a concurrent claim of the same
	// key waits for that transaction, and finds the row if it commits or
	// claims the key itself if it rolls back.
	ClaimRequestKey(ctx context.Context, k domain.RequestKey) (existing domain.RequestKey, claimed bool, err error)
}

// LockStore manages named locks. Rows are kept until deleted, so every read
// can return an expired lock; the caller judges it against its own clock.
type LockStore interface {
	// GetLock returns the org's lock of that name, or ErrNotFound. Inside a
	// transaction it holds the row until the transaction ends, so two
	// acquires of one name run one after the other.
	GetLock(ctx context.Context, orgID domain.ID, name string) (domain.Lock, error)
	// InsertLock adds a lock and returns domain.ErrLockHeld when the org
	// already has a row of that name.
	InsertLock(ctx context.Context, l domain.Lock) error
	// UpdateLockHolder rewrites holder, session, purpose, card, acquired_at
	// and expires_at of the row with l.ID, or returns ErrNotFound.
	UpdateLockHolder(ctx context.Context, l domain.Lock) error
	// RenewLock sets expires_at of the row, or returns ErrNotFound.
	RenewLock(ctx context.Context, id domain.ID, expiresAt time.Time) error
	// DeleteLock removes the row, or returns ErrNotFound.
	DeleteLock(ctx context.Context, id domain.ID) error
	// ListLocks returns the org's rows ordered by name, expired ones included.
	ListLocks(ctx context.Context, orgID domain.ID) ([]domain.Lock, error)
	// ListLiveLocks returns one page of the org's unexpired locks by name and
	// how many follow.
	ListLiveLocks(ctx context.Context, orgID domain.ID, now time.Time, pg query.Page, after string) ([]domain.Lock, int, error)
	// ListExpiredLocks returns up to limit rows that expired at or before
	// the given time, oldest first, for the sweeper.
	ListExpiredLocks(ctx context.Context, before time.Time, limit int) ([]domain.Lock, error)
}

// NoteStore manages notes and their revisions.
type NoteStore interface {
	CreateNote(ctx context.Context, n domain.Note) (domain.Note, error)
	GetNote(ctx context.Context, id domain.ID) (domain.Note, error)
	GetNotes(ctx context.Context, ids []domain.ID) ([]domain.Note, error)
	// GetNoteBySlug resolves a slug within a project.
	GetNoteBySlug(ctx context.Context, projectID domain.ID, slug string) (domain.Note, error)
	ListNotes(ctx context.Context, orgID domain.ID, f query.NoteFilter) (notes []domain.Note, remaining int, err error)
	// UpdateNote writes title, body, page_bytes, status and updated_by where
	// the stored version equals expectedVersion, keeping the replaced title,
	// body and page as a revision with the given id (the page only when
	// pageChanged). The page itself is written with PutNotePage.
	UpdateNote(ctx context.Context, n domain.Note, expectedVersion int64, revisionID domain.ID, pageChanged bool) (domain.Note, error)
	ListNoteRevisions(ctx context.Context, noteID domain.ID, pg query.HistoryPage) ([]domain.NoteRevision, error)
	GetNoteRevision(ctx context.Context, noteID domain.ID, version int64) (domain.NoteRevision, error)
	// PutNotePage, DeleteNotePage and GetNotePage are the card page methods
	// for notes.
	PutNotePage(ctx context.Context, noteID domain.ID, html, text string) error
	DeleteNotePage(ctx context.Context, noteID domain.ID) error
	GetNotePage(ctx context.Context, noteID domain.ID) (string, error)
}

// RefStore keeps resolved [[...]] references for backlinks.
type RefStore interface {
	// ReplaceRefs stores the references found in one source's body,
	// replacing the previous set. Every link must carry the same source.
	ReplaceRefs(ctx context.Context, sourceID domain.ID, links []domain.RefLink) error
	// Backlinks returns the sources that reference target.
	Backlinks(ctx context.Context, targetID domain.ID) ([]domain.RefLink, error)
}

// EventStore is the append-only log.
type EventStore interface {
	// AppendEvent stores e, whose id the caller assigned, and signals
	// listeners for the org after commit.
	AppendEvent(ctx context.Context, e domain.Event) error
	// ListEvents returns one page in feed order and how many more matching
	// events lie beyond it in the paging direction. Only events whose
	// transaction has finished are visible, so a cursor advanced past the
	// page never skips one.
	ListEvents(ctx context.Context, orgID domain.ID, f query.EventFilter) (events []domain.Event, remaining int, err error)
	// CountEventsAfter counts matching events past f.After, stopping at
	// f.Limit when positive.
	CountEventsAfter(ctx context.Context, orgID domain.ID, f query.EventFilter) (int, error)
	ListEventsForSubject(ctx context.Context, orgID domain.ID, subj domain.Subject, limit int) ([]domain.Event, error)
	// CardsCreatedInSession returns the cards among cardIDs whose
	// card.created event actor wrote in session.
	CardsCreatedInSession(ctx context.Context, orgID domain.ID, cardIDs []domain.ID, actor domain.ActorRef, session string) ([]domain.ID, error)
	// SubscribeCard subscribes the chat to the card, unless it already
	// does.
	SubscribeCard(ctx context.Context, w domain.CardSubscription) error
	// UnsubscribeCard removes every subscription of the chat to the card; no error when
	// there is none.
	UnsubscribeCard(ctx context.Context, cardID, agentID domain.ID, session string) error
	// ListCardSubscriptions returns the chat's subscriptions to cards that are not done
	// or dropped, oldest first, one per card.
	ListCardSubscriptions(ctx context.Context, agentID domain.ID, session string) ([]query.SubscribedCard, error)
	// SubscribedCardsAmong returns the cards among cardIDs that the chat is
	// subscribed to.
	SubscribedCardsAmong(ctx context.Context, orgID domain.ID, cardIDs []domain.ID, agentID domain.ID, session string) ([]domain.ID, error)
	// DeleteCardSubscriptionsOfLostChats deletes the subscriptions of chats not seen
	// since seenSince, or with no chat row, and returns how many.
	DeleteCardSubscriptionsOfLostChats(ctx context.Context, seenSince time.Time) (int, error)
	// DeleteCardSubscriptionsOfClosedCards deletes the subscriptions on cards done or
	// dropped before closedBefore, or gone, and returns how many.
	DeleteCardSubscriptionsOfClosedCards(ctx context.Context, closedBefore time.Time) (int, error)
	// CardCreatedSession returns the session label the card was created in.
	CardCreatedSession(ctx context.Context, orgID, cardID domain.ID) (string, error)
	// CardParkedFrom returns the status the card left the last time it moved
	// to waiting; ErrNotFound when it never did.
	CardParkedFrom(ctx context.Context, orgID, cardID domain.ID) (domain.Status, error)
	// LatestEventPosition returns the position of the newest visible event in
	// the org that f's ProjectIDs and Limited reach, or zero when there is
	// none. A new client starts its cursor here, so it must be an event the
	// caller may get: a cursor that moved for an event they may not would
	// tell them it happened, and when.
	LatestEventPosition(ctx context.Context, orgID domain.ID, f query.EventFilter) (query.EventPosition, error)
}

// Notifier delivers "something changed in org X" signals across server
// instances. The Postgres store implements it with LISTEN/NOTIFY.
type Notifier interface {
	// Listen calls fn for every org that gets a new event until ctx ends.
	Listen(ctx context.Context, fn func(orgID domain.ID)) error
}

// SearchStore is full-text search across cards and notes, returning ranked hits.
type SearchStore interface {
	// Search ranks matches in the org; projectIDs, when not nil, limits it to
	// those projects before ranking and the limit apply. after, when not nil,
	// continues from that hit. It also returns how many hits lie beyond the
	// page, capped at query.RemainingCap.
	Search(ctx context.Context, orgID domain.ID, projectIDs []domain.ID, query string, limit int, after *query.SearchCursor) ([]query.SearchHit, int, error)
	// SearchRank is the relevance of one card or note for the query; a ranked
	// list's cursor carries it, so that continuing reads no row by a client's id.
	SearchRank(ctx context.Context, subject domain.SubjectType, id domain.ID, query string) (float64, error)
}
